-- Référentiel médias — table ref_media
-- Généré pour import PostgreSQL / compatible MySQL (TINYINT pour actif si besoin).

CREATE TABLE IF NOT EXISTS ref_media (
    id_media      VARCHAR(16)  PRIMARY KEY,
    code          VARCHAR(32)  NOT NULL UNIQUE,
    nom           VARCHAR(120) NOT NULL,
    pays_code     CHAR(2)      NOT NULL,
    pays_nom      VARCHAR(40)  NOT NULL,
    langue        VARCHAR(8)   NOT NULL,
    type_media    VARCHAR(40)  NOT NULL,
    support       VARCHAR(24)  NOT NULL,
    periodicite   VARCHAR(24)  NOT NULL,
    thematique    VARCHAR(32)  NOT NULL,
    couverture    VARCHAR(24)  NOT NULL,
    groupe_media  VARCHAR(80)  NOT NULL,
    ville         VARCHAR(60)  NOT NULL,
    url           VARCHAR(255) NOT NULL,
    priorite_rp   SMALLINT     NOT NULL,
    actif         BOOLEAN      NOT NULL DEFAULT TRUE,
    notes         TEXT,
    source_liste  VARCHAR(16)  NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_ref_media_pays ON ref_media (pays_code);
CREATE INDEX IF NOT EXISTS idx_ref_media_type ON ref_media (type_media);
CREATE INDEX IF NOT EXISTS idx_ref_media_prio ON ref_media (priorite_rp);

